using MaintenancePRO.Services; using MaintenancePRO.Models; using System.Collections.ObjectModel; namespace MaintenancePRO.ViewModels; public sealed class EquipmentViewModel:BaseViewModel { public ObservableCollection<Equipment> Items {get;} public EquipmentViewModel(DemoDataService data){Items=data.Equipments;} string _search=""; public string Search {get=>_search;set{if(Set(ref _search,value))OnPropertyChanged(nameof(FilteredItems));}} public IEnumerable<Equipment> FilteredItems=>Items.Where(x=>(x.Name+" "+x.Code+" "+x.Location).Contains(Search,StringComparison.OrdinalIgnoreCase)); public Command<Equipment> SelectCommand=>new(async e=>{if(e!=null)await Shell.Current.GoToAsync(nameof(Views.EquipmentDetailPage),new Dictionary<string,object>{{"Equipment",e}});}); public Command AddCommand=>new(async()=>await Shell.Current.DisplayAlert("Nouvel équipement","Le formulaire sera relié au backend dans une phase ultérieure.","OK")); }